<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Quotation extends Model{protected $fillable=['business_id','customer_id','project_id','quotation_number','theme_id','issue_date','valid_until','status','currency','subtotal','discount','tax','grand_total','notes','terms','payment_schedule','document_snapshot','created_by_user_id'];protected function casts():array{return ['issue_date'=>'date','valid_until'=>'date','payment_schedule'=>'array','document_snapshot'=>'array','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','grand_total'=>'decimal:2'];}public function business(){return $this->belongsTo(Business::class);}public function customer(){return $this->belongsTo(Customer::class);}public function project(){return $this->belongsTo(Project::class);}public function createdBy(){return $this->belongsTo(User::class,'created_by_user_id');}public function invoices(){return $this->hasMany(Invoice::class);}public function sessions(){return $this->hasMany(QuotationSession::class)->orderBy('sort_order');}}
